contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        require(msg.sender != address(0));
        address depositor = c.depositorAccount();
        require(depositor != msg.sender);
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.depositorAccount() == depositor && c.number() == 0 && c.timestamp() == 0);
    }
    receive() external payable {}
}
